def solve(nums, k):
    # Count frequency of each number
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    # Find all unique numbers and sort them
    sorted_unique = sorted(count.keys())

    # Traverse sorted unique numbers to find the k-th smallest
    for num in sorted_unique:
        if k <= count[num]:
            return num
        k -= count[num]

