def solve(nums, k):
    # Count the frequency of each number
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Get the sorted list of unique numbers
    sorted_nums = sorted(freq.keys())

    # Count cumulative frequencies to find the k-th smallest
    count = 0
    for num in sorted_nums:
        count += freq[num]
        if count >= k:
            return num
